def _suite_navigation(context):
    if not context:
        return ''
    def link(item, current):
        path = item.get('path', '')
        if not isinstance(path, str) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]{0,79}', path):
            raise ValueError('Unsafe benchmark navigation path')
        active = ' aria-current="page"' if current else ''
        return '<a href="../' + path + '/index.html"' + active + '>' + html.escape(str(item['title'])) + '</a>'
    tabs = ''.join(link(s, s['id'] == context['suite']['id']) for s in context['suites'])
    return ('<nav class="suite-navigation" aria-label="Benchmark suites"><a href="../index.html">All benchmarks</a>'
        + tabs + '</nav>')


def render_document(report: dict, *, style: str = STYLE, script: str = SCRIPT, embedded_media: dict | None = None) -> str:
    """Render public data as escaped inert JSON and hash-authorized inline code."""
    payload = json.dumps(report, ensure_ascii=False, separators=(",", ":")).replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    script_hash = base64.b64encode(hashlib.sha256(script.encode()).digest()).decode()
    style_hash = base64.b64encode(hashlib.sha256(style.encode()).digest()).decode()
    csp = "default-src 'none'; script-src 'sha256-" + script_hash + "'; style-src 'sha256-" + style_hash + "'; img-src 'self'; base-uri 'none'; form-action 'none'; connect-src 'none'"
    if embedded_media is not None:
        csp = csp.replace("img-src 'self'", "img-src 'self' data:")
    embedded = json.dumps(embedded_media or {}, separators=(",", ":")).replace("<", "\\u003c").replace("&", "\\u0026")
    limits = "".join("<li>" + html.escape(str(item)) + "</li>" for item in report.get("limitations", []))
    title = str(report.get('publication', {}).get('suite', {}).get('title', ''))
    title = html.escape(title + ' benchmark' if title else 'Skill benchmark report')
    navigation = _suite_navigation(report.get('publication'))
    chapters = {key: str(index) + '. ' + label for index, (key, label) in enumerate(CHAPTERS, 1)}
    history_hidden = ' hidden' if len(report.get('experiments', [])) < 2 else ''
    contents = ''.join('<li' + (history_hidden if key == 'commit-history' else '') + '><a href="#' + key + '">' + html.escape(chapters[key]) + '</a></li>' for key, _ in CHAPTERS)
    return ('<!doctype html><html lang="en" translate="no"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="' + html.escape(csp, quote=True) + '"><title>' + title + '</title><style>' + style + '</style></head><body><main>' + navigation +
        '<header><p class="eyebrow">MAINTAINALL / SKILL BENCHMARK</p><h1 id="report-title">' + title + '</h1><div id="experiment-summary"></div><nav class="navigation" aria-label="Report navigation"><p class="contents-label">Contents</p><ol>' + contents + '</ol></nav></header>'
        + render_glossary() + '<section id="evaluation-setup"><h2>' + chapters['evaluation-setup'] + '</h2><h3>Versions and filters</h3><div class="primary-filters"><label>Candidate commit<select id="candidate-commit-select" aria-label="Candidate commit"></select></label><label>Baseline commit<select id="baseline-commit-select" aria-label="Baseline commit"></select></label><label>Evaluation run<select id="experiment-select" aria-label="experiment"></select></label><label>Case<select id="case-select" aria-label="case"></select></label></div><p id="version-status" class="caption"></p><details id="advanced-filters"><summary>More filters</summary><div id="filters"></div><button id="clear-filters">Clear filters</button></details><h3>Skill changes</h3><details id="skill-diff"><summary>View skill changes</summary><div id="skill-diff-content"></div></details></section>'
        '<section id="overview"><h2>' + chapters['overview'] + '</h2><div id="conditions-line"></div><div id="sample-metrics" class="metrics"></div><div id="review-coverage"></div><div id="overview-charts" class="chart-grid"></div><div id="ordinal-overview"></div><details id="rating-distributions"><summary>Rating distributions by evaluated condition</summary><div id="rating-charts" class="chart-full"></div></details><details><summary>Time and usage</summary><div id="usage-chart" class="chart-full"></div><div id="efficiency"></div></details></section>'
        '<section id="version-comparison"><h2>' + chapters['version-comparison'] + '</h2><p class="muted">Compare matching tasks and review conditions. Skill version is the tested variable. Results use the candidate direction; missing reviews and insufficient evidence remain separate.</p><div id="comparison-summary"></div><h3>Paired judgments</h3><div id="comparison-table"></div></section>'
        '<section id="case-evidence"><h2>' + chapters['case-evidence'] + '</h2><p class="muted">Compare actual references and output images at their original proportions. Inspect requirements, score definitions and review reasons by turn. Expand a case to inspect its references, outputs and technical checks.</p><div class="case-actions"><button id="expand-cases" type="button">Expand all cases</button><button id="collapse-cases" type="button">Collapse all cases</button><p class="caption">Summaries cover all runs under the current filters.</p></div><div id="case-panels"></div></section>'
        '<section id="commit-history"' + history_hidden + '><h2>' + chapters['commit-history'] + '</h2><div class="chart-controls"><label>Commit chart<select id="commit-metric" aria-label="Commit chart metric"><option value="distribution">Rating counts</option><option value="coverage">Ratings with enough evidence (%)</option></select></label></div><div id="commit-chart"></div><details id="experiment-history"><summary id="experiment-history-summary">All submitted experiments</summary><div id="history-timeline"></div></details><details id="cohort-history"><summary>Recorded ratings with matching conditions</summary><label>Display<select id="history-metric" aria-label="history metric"><option value="coverage">Ratings with enough evidence</option><option value="distribution">Score distribution</option></select></label><p class="caption">Uses existing rating rows, not all planned requirements or future turns. Unknown is not zero. A single experiment does not establish a trend.</p><div id="history-trends"></div></details></section>'
        '<footer class="footer"><details id="technical-details" class="technical"><summary>Technical provenance, verification and full records</summary><div id="provenance"></div><div id="technical-trials"></div><h4>Withheld previews</h4><div id="withheld-previews"></div><details><summary>Full public JSON</summary><a id="json-download" href="report.json" download>Download public JSON</a><pre id="public-json"></pre></details></details><details><summary>Scope and limitations</summary><ul class="limits">' + limits + '</ul></details><p>This report presents verified public records. Private logs, session identities and credentials are excluded.</p></footer></main><div id="term-tooltip" class="help-tooltip" role="tooltip" hidden><strong id="term-tooltip-label"></strong><p id="term-tooltip-definition"></p></div><dialog id="image-viewer"><div class="dialog-heading"><span id="image-title"></span><button id="close-image">Close</button></div><p class="caption">Shown at native pixel size. Scroll to inspect the full image.</p><div class="zoom-scroll"><img id="native-image" alt=""></div></dialog><script type="application/json" id="data">' + payload + '</script><script type="application/json" id="embedded-media">' + embedded + '</script><script>' + script + '</script></body></html>')
